<?php
function anStaffWhere(array $p,array $f): array {
    $where='filed_at>=? AND filed_at<?';$params=anBounds($p,true);if($f['staff_role']!==''){$where.=' AND staff_role=?';$params[]=$f['staff_role'];}if($f['staff_q']!==''){$q='%'.str_replace(['!','%','_'],['!!','!%','!_'],$f['staff_q']).'%';$where.=" AND (staff_id LIKE ? ESCAPE '!' OR staff_name LIKE ? ESCAPE '!' OR reference LIKE ? ESCAPE '!')";array_push($params,$q,$q,$q);}return [$where,$params];
}
function anStaff(mysqli $db,array $p,array $f): array {
    [$w,$params]=anStaffWhere($p,$f);$r=anRow($db,"SELECT COUNT(*) total,COALESCE(SUM(report_type='daily'),0) daily,COALESCE(SUM(report_type='monthly'),0) monthly,COALESCE(SUM(status='submitted'),0) pending,COALESCE(SUM(status='reviewed'),0) reviewed,COALESCE(SUM(status='returned'),0) returned FROM job_reports WHERE $w",$params);$url=anLink('superadmin/staff.php',['tab'=>'reports']);[$pw,$pp]=anStaffWhere(array_replace($p,['utc_from'=>$p['previous_utc_from'],'utc_until'=>$p['previous_utc_until']]),$f);$previous=anNumber($db,"SELECT COUNT(*) FROM job_reports WHERE $pw",$pp);$m=[];foreach(['total'=>'Filed Job Report versions','daily'=>'Daily report versions','monthly'=>'Monthly report versions','pending'=>'Cohort reports awaiting review','reviewed'=>'Reviewed report versions','returned'=>'Returned for clarification']as$key=>$label)$m[]=anMetric($key,$label,(int)$r[$key],'count','Filed during selected period','Includes filed versions; corrections preserve original submissions.',$url,$key==='total'?$previous:null);
    $source=auditReportSource($db);$aw="r.created_at>=? AND r.created_at<? AND r.role IN ('superadmin','admin','security','maintenance','treasurer') AND r.action NOT IN ('view','page_view','refresh','heartbeat','tick','login','logout','export')";$ap=anBounds($p);if($f['staff_role']!==''){$aw.=' AND r.role=?';$ap[]=$f['staff_role'];}if($f['staff_q']!==''){$aw.=" AND (r.actor LIKE ? ESCAPE '!' OR r.identifier LIKE ? ESCAPE '!')";$q='%'.str_replace(['!','%','_'],['!!','!%','!_'],$f['staff_q']).'%';array_push($ap,$q,$q);}
    $audit=anQuery($db,"SELECT r.module label,COUNT(*) value FROM ($source) r WHERE $aw GROUP BY r.module ORDER BY value DESC",$ap)->get_result()->fetch_all(MYSQLI_ASSOC);$m[]=anMetric('recorded_actions','Central staff work-action records',array_sum(array_column($audit,'value')),'count','Audit period and staff lookup','Known recorded staff roles; excludes passive views, exports and authentication. Not an employee quality score.');
    return anSection('staff',$m,[anChart('job_report_trend','Filed report versions',anTrend($db,'job_reports','filed_at',$w,$params,$p,'COUNT(*)',true),'line'),anChart('job_roles','Filed reports by recorded staff role',anGroup($db,'job_reports','staff_role',$w,$params),'donut'),anChart('job_status','Current filed-version review status',anGroup($db,'job_reports','status',$w,$params),'donut'),anChart('staff_actions','Central staff actions by module',$audit)],['Staff lookup applies to this section only, using recorded staff IDs/names/roles. Formal filed versions are different from verified work activities. Staff-reported work notes are never analyzed as verified actions.','Activity volume is not an employee performance ranking. Different roles produce different kinds and numbers of records. Private notes, case bodies and other staff-restricted records are excluded.']);
}
function anAuditLink(array $p,array $extra=[]): string {return anLink('superadmin/auditlog.php',array_merge(['mode'=>'range','start'=>$p['start'],'end'=>min($p['end'],substr($p['until'],0,10))],$extra));}
function anSystem(mysqli $db,array $p): array {
    $source=auditReportSource($db);$where="r.created_at>=? AND r.created_at<? AND r.action NOT IN ('view','page_view','refresh','heartbeat','tick')";$bounds=anBounds($p);$r=anRow($db,"SELECT COUNT(*) total,COALESCE(SUM(r.status='success'),0) success,COALESCE(SUM(r.status='failed'),0) failed,COALESCE(SUM(r.status='unknown'),0) unknown,COUNT(DISTINCT r.admin_id) active,COALESCE(SUM(r.action IN ('login','logout','password_reset','reset_password','auto_login')),0) authentication,COALESCE(SUM(r.module IN ('Staff Management','Unit Management','Accounts') AND r.action NOT IN ('login','logout')),0) changes,COALESCE(SUM(r.module='Visitor QR Scanner' AND r.status='refused'),0) refused FROM ($source) r WHERE $where",$bounds);
    $prev=anNumber($db,"SELECT COUNT(*) FROM ($source) r WHERE $where",anBounds($p,false,true));$url=anAuditLink($p);$m=[];foreach(['total'=>'Recorded meaningful events','success'=>'Explicit successful actions','failed'=>'Explicit failed actions','unknown'=>'Outcomes not recorded','active'=>'Unique active accounts','authentication'=>'Authentication events','changes'=>'Administrative changes','refused'=>'Refused QR verifications']as$key=>$label)$m[]=anMetric($key,$label,(int)$r[$key],'count','Audit timestamp in selected period','No inference from request rejection; unknown historical outcomes stay unknown.',$url,$key==='total'?$prev:null);
    $modules=anGroup($db,"($source) r",'r.module',$where,$bounds);foreach($modules as&$row)$row['url']=anAuditLink($p,['module'=>$row['label']]);unset($row);$roles=anGroup($db,"($source) r",'r.role',$where,$bounds);foreach($roles as&$row)$row['url']=anAuditLink($p,['role'=>$row['label']]);unset($row);
    $telemetry=anGroup($db,'analytics','event_type','created_at>=? AND created_at<?',$bounds);$m[]=anMetric('telemetry','Legacy usage telemetry records',array_sum(array_column($telemetry,'value')),'count','Selected period; separate from work events','Usage telemetry is not added to central audit activity totals.');$m[]=anMetric('active_residents','Residents with recorded logins',anNumber($db,"SELECT COUNT(DISTINCT a.user_id) FROM analytics a JOIN users u ON u.id=a.user_id WHERE a.event_type='user_login' AND a.created_at>=DATE_SUB(NOW(),INTERVAL 7 DAY) AND u.role='resident'"),'count','Last 7 days through refresh','Legacy usage metric retained; not physical occupancy.');
    return anSection('system',$m,[anChart('audit_trend','Meaningful central audit events',anTrend($db,"($source) r",'r.created_at',$where,$bounds,$p),'line','count',$url),anChart('audit_modules','Activity by actual module',$modules),anChart('audit_roles','Activity by recorded role',$roles,'donut'),anChart('audit_outcomes','Recorded event outcomes',anGroup($db,"($source) r",'r.status',$where,$bounds),'donut'),anChart('telemetry','Legacy usage telemetry (separate source)',$telemetry)],['Raw audit notes, credentials, IPs, QR tokens and confidential complaint information are never selected. Each audit ID contributes once.','Passive views/refreshes/ticks are excluded from meaningful-event charts. Usage telemetry remains separately labeled and is not treated as staff work.']);
}
function anHealthDefinitions(): array {
    $days=max(1,min(365,(int)appSetting('CONDO_ANALYTICS_STALE_DAYS','30')));
    return [
        'orphan_bills'=>['Invoices with missing account reference','payments p LEFT JOIN users u ON u.id=p.user_id','u.id IS NULL','p.id',anLink('superadmin/unitpayments.php')],
        'unreconciled_items'=>['Invoices with missing/mismatched bill items','payments p LEFT JOIN (SELECT payment_id,SUM(amount) total FROM bill_items GROUP BY payment_id) bi ON bi.payment_id=p.id',"p.status IN ('paid','pending','overdue') AND (bi.total IS NULL OR bi.total<>p.amount)",'p.id',anLink('superadmin/unitpayments.php')],
        'paid_without_date'=>['Paid records missing settlement timestamp','payments p',"p.status='paid' AND p.paid_at IS NULL",'p.id',anLink('superadmin/unitpayments.php',['tab'=>'history'])],
        'parking_unlinked'=>['Positive completed parking charges without a linked invoice','parking_requests pr',"pr.request_type='visitor' AND pr.actual_check_out IS NOT NULL AND pr.parking_fee>0 AND pr.fee_state NOT IN ('pending_rate_review','pending_account_review') AND pr.payment_id IS NULL",'pr.id',anLink('superadmin/parking.php',['tab'=>'visitors'])],
        'parking_invoice_mismatch'=>['Completed parking charges inconsistent with linked invoices','parking_requests pr JOIN payments p ON p.id=pr.payment_id',"pr.request_type='visitor' AND pr.actual_check_out IS NOT NULL AND pr.fee_state NOT IN ('pending_rate_review','pending_account_review') AND (pr.parking_fee<>p.amount OR (CASE WHEN JSON_VALID(pr.calculation_snapshot) THEN JSON_EXTRACT(pr.calculation_snapshot,'$.amount_cents') ELSE NULL END IS NOT NULL AND CASE WHEN JSON_VALID(pr.calculation_snapshot) THEN JSON_EXTRACT(pr.calculation_snapshot,'$.amount_cents') ELSE NULL END<>ROUND(pr.parking_fee*100)))",'pr.id',anLink('superadmin/parking.php',['tab'=>'visitors'])],
        'invalid_parking_snapshot'=>['Parking sessions with unreadable stored calculation snapshots','parking_requests pr',"pr.calculation_snapshot IS NOT NULL AND NOT JSON_VALID(pr.calculation_snapshot)",'pr.id',anLink('superadmin/parking.php',['tab'=>'visitors'])],
        'rate_reviews'=>['Parking sessions awaiting rate/account resolution','parking_requests pr',"pr.fee_state IN ('pending_rate_review','pending_account_review')",'pr.id',anLink('superadmin/parking.php',['tab'=>'visitors'])],
        'slot_mismatch'=>['Active parking with missing/inconsistent occupied slot','parking_requests pr LEFT JOIN parking_slots ps ON ps.id=pr.slot_id',"pr.request_type='visitor' AND pr.actual_check_in IS NOT NULL AND pr.actual_check_out IS NULL AND (ps.id IS NULL OR ps.status<>'occupied' OR NOT(ps.assigned_user_id <=> pr.user_id) OR NOT(ps.vehicle_plate <=> pr.vehicle_plate))",'pr.id',anLink('superadmin/parking.php',['tab'=>'visitors'])],
        'slot_without_session'=>['Occupied visitor slots without a tracked active session','parking_slots ps',"ps.slot_type='visitor' AND ps.status='occupied' AND NOT EXISTS(SELECT 1 FROM parking_requests pr WHERE pr.slot_id=ps.id AND pr.request_type='visitor' AND pr.actual_check_in IS NOT NULL AND pr.actual_check_out IS NULL)",'ps.id',anLink('superadmin/parking.php',['tab'=>'slots'])],
        'unlinked_fines'=>['Issued unpaid fines without a linked billing item','violations v',"v.review_status IN ('legacy','approved') AND v.status IN ('unpaid','disputed') AND v.fine_amount>0 AND (v.payment_id IS NULL OR v.bill_item_id IS NULL)",'v.id',anLink('superadmin/violations.php',['tab'=>'history'])],
        'undated_violations'=>['Approved violation reports without an issuance timestamp','violations v',"v.review_status='approved' AND v.reviewed_at IS NULL",'v.id',anLink('superadmin/violations.php',['tab'=>'history'])],
        'stale_requests'=>['Pending service requests older than '.$days.' days','resident_service_requests r',"r.status='pending' AND r.created_at<DATE_SUB(NOW(),INTERVAL $days DAY)",'r.id',anLink('superadmin/service_requests.php',['kind'=>'visitor'])],
    ];
}
function anHealth(mysqli $db,array $p): array {
    $metrics=[];$rows=[];foreach(anHealthDefinitions()as$key=>[$label,$from,$where,$id,$url]){$value=anNumber($db,"SELECT COUNT(*) FROM $from WHERE $where");$metrics[]=anMetric($key,$label,$value,'count','Current data quality','Read-only reference/state check. Legacy occupied slots may require investigation.',$url);$rows[]=['label'=>$label,'value'=>$value];}
    foreach(['infrastructure'=>'CPU / RAM / uptime / disk / backups','webhooks'=>'Unprocessed webhook queue','historical_occupancy'=>'Historical occupancy reconstruction']as$key=>$label)$metrics[]=anMetric($key,$label,null,'count','Monitoring not configured','No reliable instrumentation or authoritative history is recorded.');
    return anSection('health',$metrics,[anChart('data_quality','Current measurable data-quality issues',$rows)],['Data quality checks are read-only and never repair records or run parking monitoring. Stale request age is a review aid, not an overdue/SLA claim.','A completed analytics query does not certify server availability, backup quality or provider delivery. Missing instrumentation is explicitly not configured.']);
}
function anFindMetric(array $sections,string $section,string $key): ?array {foreach($sections[$section]['metrics']??[]as$m)if($m['key']===$key)return $m;return null;}
function anOverview(mysqli $db,array $p,array $sections): array {
    $m=[];foreach(['units'=>['total','occupied','vacant'],'financial'=>['collected','outstanding'],'parking'=>['active_visitors','active_vehicles'],'maintenance'=>['open']]as$section=>$keys)if(array_key_exists($section,$sections))foreach($keys as$key){$metric=anFindMetric($sections,$section,$key);if($metric)$m[]=array_merge($metric,['key'=>$section.'_'.$key]);else$m[]=anMetric($section.'_'.$key,ucfirst($section).' '.str_replace('_',' ',$key),null,'count','Section unavailable');}
    $role=anActor($db)['role'];$queues=[];
    foreach([
        'Resident accounts'=>['users',"role='resident' AND status='pending'",'accounts.review','superadmin/pending_accounts.php',[]],
        'Visitor registrations'=>['resident_service_requests',"request_kind='visitor' AND status='pending'",'visitors.review','superadmin/service_requests.php',['kind'=>'visitor']],
        'Permit registrations'=>['resident_service_requests',"request_kind='permit' AND status='pending'",'permits.review','superadmin/service_requests.php',['kind'=>'permit']],
        'Amenity bookings'=>['bookings',"status='pending'",'bookings.review','superadmin/bookingrequest.php',['status'=>'pending']],
        'Parking requests'=>['parking_requests',"status='pending'",'parking.review','superadmin/parking.php',['tab'=>'visitors']],
        'Parking extensions'=>['parking_extensions',"status='pending'",'parking.extensions.review','superadmin/parking.php',['tab'=>'extensions']],
        'Vehicle registrations'=>['vehicles',"status='pending'",'vehicles.review','superadmin/registeredvehicles.php',[]]
    ]as$label=>[$table,$where,$capability,$route,$query])if(roleHasCapability($role,$capability))$queues[]=['label'=>$label,'value'=>anNumber($db,"SELECT COUNT(*) FROM $table WHERE $where"),'url'=>anLink($route,$query)];
    $m[]=anMetric('pending_approvals','Pending operational decisions',array_sum(array_column($queues,'value')),'count','Current live approval queues','Pending records across authorized listed queues. Linked requests can require more than one decision.');
    $failed=count(array_filter($sections,static fn($s)=>!$s['available']));$m[]=anMetric('retrieval','Unavailable analytics sections',$failed,'count','This retrieval','A failed query is unavailable, never silently converted to zero.');
    return anSection('overview',$m,[anChart('approval_queues','Current pending approval queues',$queues)],['Live inventory/backlog metrics describe the state at refresh. Financial/activity metrics use the selected period and explicit event dates. Historical outstanding balances and occupancy trends are unavailable where no trustworthy ledger exists.',$p['partial']?'The current period is partial. Comparisons use matched elapsed time in the previous period (capped to its calendar end).':'Comparisons use the previous equivalent complete period.']);
}
function anInsights(array $p,array $sections): array {
    $result=[];$add=static function($title,$section,$metric,$rule,$severity='information')use(&$result,$p){$result[]=['title'=>$title,'metric'=>$metric['label'],'value'=>$metric['value'],'unit'=>$metric['unit'],'context'=>$metric['context'],'period'=>$p['label'],'rule'=>$rule,'severity'=>$severity,'url'=>$metric['url']];};
    $parking=anFindMetric($sections,'parking','slot_occupancy');$threshold=max(1,min(100,(float)appSetting('CONDO_ANALYTICS_PARKING_THRESHOLD','85')));if($parking&&$parking['value']!==null&&$parking['value']>=$threshold)$add('Visitor slot occupancy reached the configured review threshold','parking',$parking,'Current recorded occupancy >= '.$threshold.'%.','review');
    $open=anFindMetric($sections,'maintenance','open');$limit=max(1,(int)appSetting('CONDO_ANALYTICS_MAINTENANCE_THRESHOLD','20'));if($open&&$open['value']>=$limit)$add('Review the unresolved maintenance backlog','maintenance',$open,'Current unresolved requests >= '.$limit.'. No overdue/SLA inference.','review');
    $pending=anFindMetric($sections,'staff','pending');$limit=max(1,(int)appSetting('CONDO_ANALYTICS_REPORT_THRESHOLD','5'));if($pending&&$pending['value']>=$limit)$add('Filed report versions are awaiting review','staff',$pending,'Selected filing cohort has at least '.$limit.' submitted versions.','review');
    $overdue=anFindMetric($sections,'financial','overdue');$limit=max(0,(int)appSetting('CONDO_ANALYTICS_OVERDUE_THRESHOLD_CENTS','100000'));if($overdue&&$overdue['value']>=$limit&&$overdue['value']>0)$add('Review recorded overdue billing','financial',$overdue,'Current overdue invoice balance >= PHP '.number_format($limit/100,2).'.','review');
    $entries=anFindMetric($sections,'parking','entries');$growth=max(1,(float)appSetting('CONDO_ANALYTICS_GROWTH_THRESHOLD','20'));if($entries&&$entries['previous']>0&&$entries['change']>=10&&$entries['percent_change']>=$growth)$add('Confirmed visitor entries increased in the comparable period','parking',$entries,'At least 10 additional entries and >= '.$growth.'% increase against '.$p['comparison_label'].'.');
    $review=anFindMetric($sections,'parking','reviews');if($review&&$review['value']>0)$add('Parking charges require authorized rate/account review','parking',$review,'At least one unresolved review; no provisional revenue is counted.','review');
    if(!$result)$result[]=['title'=>count(array_filter($sections,static fn($s)=>!$s['available']))?'Some analytics are unavailable; insights are incomplete':'Available calculations did not reach a configured review threshold','metric'=>'Supported calculations only','value'=>null,'unit'=>'count','context'=>'No causal explanation is inferred. Missing historical baselines remain unavailable.','period'=>$p['label'],'rule'=>'Insights use the documented thresholds and available sections. This is not a blanket health certification.','severity'=>'information','url'=>null];return $result;
}
function anDetail(mysqli $db,array $input): array {
    anActor($db);auditReportBeginSnapshot($db);try{$data=anDetailRows($db,$input);$db->commit();return $data;}catch(Throwable $e){$db->rollback();throw $e;}
}
function anDetailRows(mysqli $db,array $input): array {
    $actor=anActor($db);$f=anInput($input);$p=$f['period'];$page=filter_var($input['page']??1,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>1000000]]);if($page===false)throw new DomainException('Invalid page.');$kind=$input['kind']??'';if(!is_string($kind))throw new DomainException('Choose a supported detail list.');
    if($kind==='staff'){
        if(!isset(anSections($actor)['staff']))throw new DomainException('Access denied.',403);[$where,$params]=anStaffWhere($p,$f);$total=anNumber($db,"SELECT COUNT(*) FROM job_reports WHERE $where",$params);$pages=max(1,(int)ceil($total/25));$page=min($page,$pages);$offset=($page-1)*25;$rows=anQuery($db,"SELECT id,reference,staff_id,staff_name,staff_role,report_type,status,filed_at FROM job_reports WHERE $where ORDER BY filed_at DESC,id DESC LIMIT 25 OFFSET $offset",$params)->get_result()->fetch_all(MYSQLI_ASSOC);foreach($rows as&$r){$r['filed_at']=(new DateTimeImmutable($r['filed_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Manila'))->format('Y-m-d H:i:s');$r['url']=anLink('superadmin/staff.php',['tab'=>'reports','job_report'=>$r['id']]);}unset($r);return compact('rows','total','page','pages')+['kind'=>'staff'];
    }
    if($kind==='maintenance_open'){if(!isset(anSections($actor)['maintenance']))throw new DomainException('Access denied.',403);$where="status IN ('pending','approved','in_progress','reopened')";$total=anNumber($db,"SELECT COUNT(*) FROM maintenance_requests WHERE $where");$pages=max(1,(int)ceil($total/25));$page=min($page,$pages);$offset=($page-1)*25;$rows=anQuery($db,"SELECT id,issue_type category,status,created_at FROM maintenance_requests WHERE $where ORDER BY created_at DESC,id DESC LIMIT 25 OFFSET $offset")->get_result()->fetch_all(MYSQLI_ASSOC);foreach($rows as&$r){$r['reference']='MR-'.$r['id'];$r['url']=anLink('superadmin/maintenancerequests.php',['view'=>$r['id']]);}unset($r);return compact('rows','total','page','pages')+['kind'=>'maintenance'];}
    if(!isset(anSections($actor)['health']))throw new DomainException('Access denied.',403);$defs=anHealthDefinitions();if(!isset($defs[$kind]))throw new DomainException('Choose a supported issue list.');[$label,$from,$where,$id,$url]=$defs[$kind];$total=anNumber($db,"SELECT COUNT(*) FROM $from WHERE $where");$pages=max(1,(int)ceil($total/25));$page=min($page,$pages);$offset=($page-1)*25;$raw=anQuery($db,"SELECT $id id FROM $from WHERE $where ORDER BY $id DESC LIMIT 25 OFFSET $offset")->get_result()->fetch_all(MYSQLI_ASSOC);$rows=array_map(static fn($r)=>['reference'=>'Record #'.$r['id'],'issue'=>$label,'url'=>$url],$raw);return compact('rows','total','page','pages')+['kind'=>'health'];
}
